from range_compression import compress_ranges


def test_mixed_ranges():
    assert compress_ranges([1, 2, 3, 5, 7, 8]) == ['1-3', '5', '7-8']


def test_empty_and_duplicates():
    assert compress_ranges([]) == []
    assert compress_ranges([4, 4, 4]) == ['4']


def test_negative_values():
    assert compress_ranges([-3, -2, 0]) == ['-3--2', '0']
